// Auto-generated flat-style brand illustrations (no external image dependency)
window.ULAW_groupScene = function(group){
  var map = {
    business: {scene:"study_group", bg:"navy"},
    finance: {scene:"handshake_business", bg:"purple"},
    digital: {scene:"laptop_tech", bg:"green"},
  };
  return map[group] || map.business;
};
window.ULAW_sceneSvg = function(scene, bg){
  var scenes = window.ULAW_SCENES || {};
  return scenes[scene + "__" + bg] || "";
};

