// ---------------------------------------------------------------------------
// Wide 16:9 hero illustrations (labelled "Ảnh minh họa" wherever shown).
// Subjects sit in x≈760–1500 so they survive the desktop overlay (left ~45%
// covered by the H1 panel); crops anchor right (xMaxYMid) for the 4:3 mobile view.
// ---------------------------------------------------------------------------
(function(){
  var C = {p:"#2D55A8", pi:"#1F3F82", d:"#2B6595", t:"#459787", pu:"#97589A", o:"#F19E4B", tint:"#E8EEF8", tint2:"#D5E1F3", w:"#fff", skin:"#F2C9A8"};

  function person(x, y, s, body, hair){
    s = s || 1;
    return '<g transform="translate('+x+' '+y+') scale('+s+')">' +
      '<rect x="-34" y="46" width="68" height="96" rx="30" fill="'+body+'"/>' +
      '<circle cx="0" cy="18" r="28" fill="'+C.skin+'"/>' +
      '<path d="M-29 14 a29 29 0 0 1 58 0 q-10 -8 -29 -8 t-29 8z" fill="'+(hair||C.pi)+'"/>' +
    '</g>';
  }
  function books(x, y){
    return '<g transform="translate('+x+' '+y+')">' +
      '<rect x="0" y="48" width="150" height="22" rx="4" fill="'+C.d+'"/>' +
      '<rect x="10" y="26" width="132" height="22" rx="4" fill="'+C.t+'"/>' +
      '<rect x="-4" y="4" width="140" height="22" rx="4" fill="'+C.o+'"/>' +
    '</g>';
  }
  function iconCircle(cx, cy, r, fill, inner){
    return '<g transform="translate('+cx+' '+cy+')"><circle r="'+r+'" fill="'+fill+'"/>'+inner+'</g>';
  }
  var briefcase = '<rect x="-26" y="-14" width="52" height="36" rx="6" fill="#fff"/><rect x="-10" y="-24" width="20" height="12" rx="3" fill="none" stroke="#fff" stroke-width="5"/>';
  var scales = '<line x1="0" y1="-26" x2="0" y2="22" stroke="#fff" stroke-width="5"/><line x1="-26" y1="-16" x2="26" y2="-16" stroke="#fff" stroke-width="5"/><path d="M-26 -16 l-12 22 h24z M26 -16 l-12 22 h24z" fill="#fff"/><rect x="-14" y="20" width="28" height="6" rx="3" fill="#fff"/>';
  var chip = '<rect x="-20" y="-20" width="40" height="40" rx="6" fill="none" stroke="#fff" stroke-width="5"/><rect x="-8" y="-8" width="16" height="16" fill="#fff"/><path d="M-10 -28v8M0 -28v8M10 -28v8M-10 20v8M0 20v8M10 20v8M-28 -10h8M-28 0h8M-28 10h8M20 -10h8M20 0h8M20 10h8" stroke="#fff" stroke-width="4"/>';

  function frame(bg, inner){
    return '<svg viewBox="0 0 1600 900" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" preserveAspectRatio="xMaxYMid slice">' +
      '<defs><linearGradient id="hg-'+bg+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F3F7FC"/><stop offset="1" stop-color="'+C.tint2+'"/></linearGradient></defs>' +
      '<rect width="1600" height="900" fill="url(#hg-'+bg+')"/>' +
      '<circle cx="1320" cy="190" r="120" fill="'+C.tint+'"/>' +
      '<rect x="0" y="720" width="1600" height="180" fill="'+C.tint2+'"/>' +
      '<rect x="0" y="716" width="1600" height="8" fill="'+C.d+'" opacity=".18"/>' +
      inner + '</svg>';
  }

  var programs = frame("a",
    // campus building
    '<rect x="820" y="330" width="460" height="390" fill="'+C.p+'"/>' +
    '<polygon points="800,335 1050,210 1300,335" fill="'+C.pi+'"/>' +
    '<rect x="800" y="330" width="500" height="18" fill="'+C.pi+'"/>' +
    '<g fill="#fff" opacity=".9">' +
      '<rect x="860" y="380" width="26" height="300" rx="4"/><rect x="930" y="380" width="26" height="300" rx="4"/>' +
      '<rect x="1144" y="380" width="26" height="300" rx="4"/><rect x="1214" y="380" width="26" height="300" rx="4"/>' +
    '</g>' +
    '<rect x="1000" y="560" width="100" height="160" rx="8" fill="'+C.pi+'"/>' +
    '<circle cx="1050" cy="290" r="22" fill="'+C.o+'"/>' +
    // Business / Law / Technology icons
    iconCircle(1390, 330, 58, C.p, briefcase) +
    iconCircle(1440, 500, 58, C.d, scales) +
    iconCircle(1350, 660, 50, C.t, chip) +
    // students in front
    person(900, 610, 1.05, C.t) + person(1000, 640, 1.1, C.o, "#3a2a1f") + person(1180, 620, 1.05, C.pu)
  );

  var learning = frame("b",
    // bookshelf
    '<rect x="1230" y="250" width="200" height="470" rx="10" fill="'+C.pi+'"/>' +
    '<g>' +
      '<rect x="1250" y="280" width="30" height="110" fill="'+C.o+'"/><rect x="1286" y="296" width="26" height="94" fill="'+C.t+'"/><rect x="1318" y="286" width="34" height="104" fill="#fff"/><rect x="1358" y="300" width="24" height="90" fill="'+C.pu+'"/>' +
      '<rect x="1250" y="420" width="36" height="110" fill="#fff"/><rect x="1292" y="436" width="28" height="94" fill="'+C.p+'"/><rect x="1326" y="426" width="30" height="104" fill="'+C.o+'"/><rect x="1362" y="440" width="44" height="90" fill="'+C.t+'"/>' +
      '<rect x="1250" y="560" width="160" height="12" fill="#fff" opacity=".4"/>' +
    '</g>' +
    // desk + laptop
    '<rect x="780" y="560" width="440" height="22" rx="8" fill="'+C.d+'"/>' +
    '<rect x="810" y="582" width="16" height="138" fill="'+C.d+'"/><rect x="1174" y="582" width="16" height="138" fill="'+C.d+'"/>' +
    '<rect x="930" y="430" width="200" height="130" rx="10" fill="'+C.pi+'"/>' +
    '<rect x="946" y="446" width="168" height="98" rx="4" fill="#fff"/>' +
    '<rect x="962" y="464" width="90" height="10" rx="4" fill="'+C.p+'"/><rect x="962" y="484" width="130" height="8" rx="4" fill="'+C.tint2+'"/><rect x="962" y="500" width="110" height="8" rx="4" fill="'+C.tint2+'"/><rect x="962" y="516" width="70" height="8" rx="4" fill="'+C.t+'"/>' +
    books(800, 490) +
    // floating documents
    '<g transform="translate(840 250) rotate(-8)"><rect width="120" height="150" rx="10" fill="#fff"/><rect x="18" y="24" width="70" height="10" rx="4" fill="'+C.p+'"/><rect x="18" y="48" width="84" height="8" rx="4" fill="'+C.tint2+'"/><rect x="18" y="66" width="84" height="8" rx="4" fill="'+C.tint2+'"/><rect x="18" y="84" width="60" height="8" rx="4" fill="'+C.tint2+'"/></g>' +
    '<g transform="translate(1020 200) rotate(6)"><rect width="120" height="150" rx="10" fill="#fff"/><rect x="18" y="24" width="60" height="10" rx="4" fill="'+C.t+'"/><rect x="18" y="48" width="84" height="8" rx="4" fill="'+C.tint2+'"/><rect x="18" y="66" width="70" height="8" rx="4" fill="'+C.tint2+'"/></g>' +
    person(1020, 600, 1.1, C.p) + person(1160, 610, 1.0, C.t, "#3a2a1f")
  );

  var admissions = frame("c",
    // steps / path
    '<path d="M780 720 h160 v-70 h160 v-70 h160 v-70 h160 v280z" fill="'+C.p+'" opacity=".92"/>' +
    '<path d="M940 650 h160 M1100 580 h160 M1260 510 h160" stroke="#fff" stroke-width="6" opacity=".5"/>' +
    // calendar card
    '<g transform="translate(820 260)"><rect width="220" height="200" rx="16" fill="#fff"/><rect width="220" height="54" rx="16" fill="'+C.d+'"/><rect y="38" width="220" height="16" fill="'+C.d+'"/>' +
      '<g fill="'+C.tint2+'"><rect x="24" y="78" width="36" height="30" rx="6"/><rect x="72" y="78" width="36" height="30" rx="6"/><rect x="120" y="78" width="36" height="30" rx="6"/><rect x="168" y="78" width="30" height="30" rx="6"/>' +
      '<rect x="24" y="120" width="36" height="30" rx="6"/><rect x="120" y="120" width="36" height="30" rx="6"/><rect x="168" y="120" width="30" height="30" rx="6"/></g>' +
      '<rect x="72" y="120" width="36" height="30" rx="6" fill="'+C.o+'"/></g>' +
    // graduation cap
    '<g transform="translate(1250 250)"><polygon points="0,40 120,-10 240,40 120,90" fill="'+C.pi+'"/><path d="M50 62 v50 q70 34 140 0 v-50 l-70 28z" fill="'+C.p+'"/><line x1="226" y1="44" x2="226" y2="118" stroke="'+C.o+'" stroke-width="6"/><circle cx="226" cy="124" r="10" fill="'+C.o+'"/></g>' +
    person(1330, 360, 1.05, C.t) + person(1180, 450, 1.0, C.pu, "#3a2a1f") + person(1010, 520, 1.0, C.o)
  );

  // Graduation: graduates in gowns throwing caps, diploma, confetti.
  function cap(x, y, s, rot){
    return '<g transform="translate('+x+' '+y+') rotate('+(rot||0)+') scale('+(s||1)+')">' +
      '<polygon points="-46,0 0,-20 46,0 0,20" fill="'+C.pi+'"/><rect x="-18" y="8" width="36" height="16" rx="3" fill="'+C.pi+'"/>' +
      '<line x1="40" y1="2" x2="46" y2="34" stroke="'+C.o+'" stroke-width="4"/><circle cx="46" cy="38" r="6" fill="'+C.o+'"/></g>';
  }
  function graduate(x, y, s, sash){
    return '<g transform="translate('+x+' '+y+') scale('+s+')">' +
      '<path d="M-44 60 Q0 36 44 60 L56 190 H-56 Z" fill="'+C.pi+'"/>' +
      '<path d="M-20 52 L0 150 L20 52" fill="none" stroke="'+sash+'" stroke-width="12"/>' +
      '<circle cx="0" cy="18" r="28" fill="'+C.skin+'"/>' +
      '<polygon points="-40,-6 0,-24 40,-6 0,12" fill="#16294f"/><rect x="-16" y="2" width="32" height="12" rx="3" fill="#16294f"/>' +
      '<line x1="34" y1="-4" x2="40" y2="26" stroke="'+C.o+'" stroke-width="3"/>' +
      '</g>';
  }
  var confetti = '';
  [[720,160,C.o],[860,110,C.t],[980,190,C.pu],[1120,90,C.o],[1260,150,C.t],[1400,110,C.pu],[1480,220,C.o],[800,260,C.pu],[1340,260,C.o]].forEach(function(c,i){
    confetti += '<rect x="'+c[0]+'" y="'+c[1]+'" width="14" height="8" rx="2" fill="'+c[2]+'" transform="rotate('+(i*37%90)+' '+c[0]+' '+c[1]+')"/>';
  });
  var graduation = frame("d",
    confetti +
    cap(900, 200, 1.0, -18) + cap(1170, 130, 1.15, 12) + cap(1410, 240, .9, -8) +
    // stage
    '<rect x="700" y="690" width="880" height="30" rx="8" fill="'+C.d+'" opacity=".35"/>' +
    graduate(880, 470, 1.25, C.o) + graduate(1100, 430, 1.45, C.t) + graduate(1330, 480, 1.2, C.pu) +
    // diploma scroll
    '<g transform="translate(1180 620) rotate(-10)"><rect x="-70" y="-16" width="140" height="32" rx="16" fill="#fff"/>' +
      '<circle cx="-70" cy="0" r="16" fill="#EDEFF5"/><rect x="-10" y="-17" width="20" height="34" fill="'+C.o+'"/></g>'
  );
  window.ULAW_HERO_SCENES = {"hero-programs": programs, "hero-learning": learning, "hero-admissions": admissions, "hero-graduation": graduation};
  window.ULAW_heroSvg = function(key){ return window.ULAW_HERO_SCENES[key] || programs; };
})();

// Animated, vivid demo art for the home highlights slider (ULAW_HIGHLIGHTS items with status "illustrative").
// Art sits on the right; the left/bottom stays calm for the caption. Motion classes live in styles.css (.hla-*).
(function(){
  function svg(id, c1, c2, c3, inner){
    return '<svg viewBox="0 0 1600 900" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" preserveAspectRatio="xMidYMid slice">' +
      '<defs><linearGradient id="hla-' + id + '" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="' + c1 + '"/><stop offset=".55" stop-color="' + c2 + '"/><stop offset="1" stop-color="' + c3 + '"/></linearGradient>' +
      '<radialGradient id="hlg-' + id + '" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#fff" stop-opacity=".55"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs>' +
      '<rect width="1600" height="900" fill="url(#hla-' + id + ')"/>' +
      '<circle class="hla-drift" cx="1250" cy="260" r="330" fill="url(#hlg-' + id + ')"/>' +
      '<circle class="hla-drift2" cx="260" cy="120" r="220" fill="#fff" opacity=".07"/>' +
      '<circle class="hla-drift" cx="1500" cy="820" r="260" fill="#fff" opacity=".06"/>' + inner + '</svg>';
  }
  function confetti(cols){
    var out = '', xs = [760, 860, 980, 1090, 1190, 1300, 1420, 1510, 820, 1040, 1260, 1460];
    xs.forEach(function(x, i){
      out += '<rect class="hla-fall hla-d' + (i % 6) + '" x="' + x + '" y="' + (60 + (i * 53) % 260) + '" width="' + (14 + i % 3 * 6) + '" height="' + (22 - i % 3 * 5) + '" rx="3" fill="' + cols[i % cols.length] + '"/>';
    });
    return out;
  }
  var event = svg('ev', '#FF3D7F', '#8B3DFF', '#2D55FF',
    // spotlights
    '<polygon class="hla-sway" points="900,0 980,0 1180,760 1000,760" fill="#fff" opacity=".13"/>' +
    '<polygon class="hla-sway2" points="1420,0 1500,0 1330,760 1150,760" fill="#fff" opacity=".13"/>' +
    confetti(['#FFD84D', '#5EF2C1', '#fff', '#FF9F43']) +
    // stage + podium + banner
    '<rect x="760" y="720" width="840" height="180" fill="#1B1450" opacity=".55"/>' +
    '<rect x="840" y="330" width="560" height="120" rx="18" fill="#fff" opacity=".95"/>' +
    '<rect x="880" y="362" width="300" height="22" rx="11" fill="#8B3DFF"/><rect x="880" y="398" width="200" height="16" rx="8" fill="#FF3D7F"/>' +
    '<circle cx="1320" cy="390" r="36" fill="#FFD84D"/>' +
    '<path d="M1060 560h200l-24 170h-152z" fill="#FFD84D"/><rect x="1040" y="540" width="240" height="30" rx="10" fill="#fff"/>' +
    '<rect x="1156" y="470" width="8" height="74" fill="#fff"/><circle class="hla-pulse" cx="1160" cy="462" r="16" fill="#fff"/>' +
    // audience heads
    '<g fill="#1B1450"><circle cx="880" cy="800" r="34"/><circle cx="980" cy="815" r="30"/><circle cx="1360" cy="805" r="34"/><circle cx="1470" cy="820" r="30"/></g>');

  var notice = svg('nt', '#FF7A18', '#FF3D54', '#B8157A',
    // ripples from the megaphone
    '<g fill="none" stroke="#fff" stroke-width="10" stroke-linecap="round">' +
      '<path class="hla-ring hla-d0" d="M1330 330a150 150 0 0 1 0 220"/><path class="hla-ring hla-d2" d="M1390 280a230 230 0 0 1 0 320"/><path class="hla-ring hla-d4" d="M1450 230a310 310 0 0 1 0 420"/></g>' +
    // megaphone
    '<g class="hla-bob"><path d="M960 380l300-120v360l-300-120z" fill="#fff"/><rect x="880" y="380" width="100" height="120" rx="22" fill="#FFD84D"/>' +
      '<rect x="920" y="490" width="44" height="120" rx="18" fill="#FFD84D" transform="rotate(-12 942 550)"/><rect x="1250" y="250" width="34" height="380" rx="17" fill="#FFE7A8"/></g>' +
    // notification cards
    '<g class="hla-slide"><rect x="780" y="660" width="380" height="96" rx="22" fill="#fff"/><circle cx="836" cy="708" r="26" fill="#FF3D54"/>' +
      '<rect x="880" y="688" width="220" height="16" rx="8" fill="#1B1450" opacity=".8"/><rect x="880" y="716" width="150" height="12" rx="6" fill="#1B1450" opacity=".35"/></g>' +
    // bell
    '<g class="hla-ring-bell" transform-origin="820 200"><path d="M760 250q0-90 60-100q60 10 60 100l20 40h-160z" fill="#FFD84D"/><circle cx="820" cy="305" r="16" fill="#FFD84D"/>' +
      '<circle cx="870" cy="160" r="22" fill="#fff"/><text x="870" y="168" text-anchor="middle" font-family="Arial" font-weight="700" font-size="24" fill="#FF3D54">!</text></g>');

  var bars = '';
  [[1010, 200], [1090, 290], [1170, 240], [1250, 360], [1330, 430]].forEach(function(b, i){
    bars += '<rect class="hla-grow hla-d' + i + '" x="' + b[0] + '" y="' + (620 - b[1]) + '" width="56" height="' + b[1] + '" rx="10" fill="' + ['#5EF2C1', '#FFD84D', '#fff', '#5EF2C1', '#FFD84D'][i] + '"/>';
  });
  var activity = svg('ac', '#00C9A7', '#0098C7', '#2D55FF',
    '<rect x="960" y="140" width="480" height="500" rx="30" fill="#fff" opacity=".14"/>' + bars +
    '<polyline class="hla-draw" points="1000,470 1110,380 1190,420 1270,280 1370,200" fill="none" stroke="#FF3D7F" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<g class="hla-glow"><circle cx="1480" cy="200" r="60" fill="#FFD84D"/><rect x="1458" y="258" width="44" height="40" rx="8" fill="#fff"/></g>' +
    // students
    '<g><circle class="hla-bob" cx="840" cy="560" r="44" fill="#FFD84D"/><rect x="786" y="610" width="108" height="150" rx="40" fill="#FFD84D"/>' +
      '<circle class="hla-bob2" cx="1480" cy="560" r="44" fill="#FF7A9C"/><rect x="1426" y="610" width="108" height="150" rx="40" fill="#FF7A9C"/></g>' +
    '<rect x="740" y="740" width="860" height="30" rx="15" fill="#0B3B6B" opacity=".55"/>');

  var stars = '';
  [[820, 160], [960, 90], [1480, 120], [1540, 330], [880, 360], [1380, 60]].forEach(function(p, i){
    stars += '<path class="hla-twinkle hla-d' + i + '" transform="translate(' + p[0] + ' ' + p[1] + ')" d="M0-22L6-6 22 0 6 6 0 22-6 6-22 0-6-6z" fill="#FFD84D"/>';
  });
  var admissions = svg('ad', '#1230A8', '#3D5CFF', '#00C2FF',
    stars +
    // stairs up
    '<g fill="#fff"><rect x="820" y="700" width="160" height="200" opacity=".25"/><rect x="980" y="610" width="160" height="290" opacity=".35"/>' +
      '<rect x="1140" y="520" width="160" height="380" opacity=".45"/><rect x="1300" y="430" width="160" height="470" opacity=".6"/></g>' +
    '<path class="hla-draw" d="M860 690 L1060 600 L1220 510 L1380 420" fill="none" stroke="#FFD84D" stroke-width="10" stroke-dasharray="4 22" stroke-linecap="round"/>' +
    // floating cap
    '<g class="hla-bob"><polygon points="1380,230 1560,300 1380,370 1200,300" fill="#0B1A5C"/><path d="M1270 330v70q110 50 220 0v-70l-110 40z" fill="#0B1A5C"/>' +
      '<line x1="1540" y1="306" x2="1540" y2="400" stroke="#FFD84D" stroke-width="8"/><circle cx="1540" cy="408" r="14" fill="#FFD84D"/></g>');

  window.ULAW_HL_SCENES = {'hl-event': event, 'hl-notice': notice, 'hl-activity': activity, 'hl-admissions': admissions};
})();
